// Define o dia do resumo: no agendamento das 7h é hoje; no link de prévia aceita ?data=AAAA-MM-DD.
const j = $input.first().json;
const viaLink = Boolean(j.headers || j.query);
const pedido = String((j.query && j.query.data) || '');
const hoje = $now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd');
const data = /^\d{4}-\d{2}-\d{2}$/.test(pedido) ? pedido : hoje;
return [{ json: { data, origem: viaLink ? 'previa' : 'agendado' } }];

// Monta o e-mail da agenda do dia no estilo da EmilIA. Só dados administrativos fictícios.
const data = $('Definir o dia').first().json.data;
const sessoes = $input.all().map(i => i.json).filter(r => r && r.id_sessao).sort((a, b) => String(a.horario).localeCompare(String(b.horario)));
const d = DateTime.fromISO(data, { zone: 'America/Sao_Paulo' }).setLocale('pt-BR');
const t0 = d.toFormat("cccc, dd 'de' LLLL 'de' yyyy"); const titulo = t0.charAt(0).toUpperCase() + t0.slice(1);
const ativas = sessoes.filter(s => ['agendada', 'confirmada', 'realizada'].includes(String(s.status).toLowerCase()));
const fora = sessoes.filter(s => !ativas.includes(s));
const pend = ativas.filter(s => ['pendente', 'atrasado'].includes(String(s.status_pagamento).toLowerCase()));
const brl = v => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
const cor = { confirmada: '#3F7D5A', agendada: '#4C6F8F', realizada: '#65776C', cancelada: '#B04A3A', remarcada: '#B8862B', falta: '#B04A3A' };
const linha = s => '<tr><td style="padding:10px 12px;border-bottom:1px solid #E3E6E0;font-weight:600;white-space:nowrap">' + s.horario + '</td>'
  + '<td style="padding:10px 12px;border-bottom:1px solid #E3E6E0">' + s.nome_paciente + ' <span style="color:#8E9B93">(' + s.codigo_paciente + ')</span></td>'
  + '<td style="padding:10px 12px;border-bottom:1px solid #E3E6E0">' + (s.tipo_atendimento || '') + '</td>'
  + '<td style="padding:10px 12px;border-bottom:1px solid #E3E6E0;color:' + (cor[String(s.status).toLowerCase()] || '#1D2924') + '">' + s.status + '</td>'
  + '<td style="padding:10px 12px;border-bottom:1px solid #E3E6E0">' + (s.status_pagamento || '') + '</td></tr>';
const tabela = rows => '<table style="width:100%;border-collapse:collapse;font-size:14px"><tr style="text-align:left;color:#65776C;font-size:11px;text-transform:uppercase;letter-spacing:.06em"><th style="padding:8px 12px">Hora</th><th style="padding:8px 12px">Paciente</th><th style="padding:8px 12px">Tipo</th><th style="padding:8px 12px">Status</th><th style="padding:8px 12px">Pagamento</th></tr>' + rows.map(linha).join('') + '</table>';
const corpo = ativas.length ? tabela(ativas) : '<p style="color:#65776C">Nenhuma sessão ativa neste dia.</p>';
const html = '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EmilIA · Agenda do dia</title>'
 + '<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600&family=Inter:wght@400;500;600&display=swap" rel="stylesheet"></head>'
 + '<body style="margin:0;background:#F5F5F0;font-family:Inter,Arial,sans-serif;color:#1D2924"><div style="max-width:680px;margin:0 auto;padding:24px 16px">'
 + '<div style="background:#1D2924;border-radius:16px 16px 0 0;padding:22px 26px;display:flex;align-items:center;gap:20px"><img src="__LOGO__" alt="emilIA" style="height:56px"><div><div style="font-family:Cormorant Garamond,Georgia,serif;font-size:26px;color:#F5F5F0">Agenda do dia</div><div style="color:#C7D2C2;font-size:13px">' + titulo + '</div></div></div>'
 + '<div style="background:#fff;border:1px solid #E3E6E0;border-top:none;border-radius:0 0 16px 16px;padding:22px 26px">'
 + '<p style="margin:0 0 16px">Bom dia! Hoje são <b>' + ativas.length + '</b> sessão(ões) na agenda' + (pend.length ? ', <b>' + pend.length + '</b> com pagamento pendente ou atrasado' : '') + '.</p>'
 + corpo
 + (fora.length ? '<p style="margin:18px 0 6px;color:#65776C;font-size:12px;text-transform:uppercase;letter-spacing:.06em">Canceladas, remarcadas ou faltas</p>' + tabela(fora) : '')
 + '<p style="margin:20px 0 0;padding:12px 14px;background:#EEF2EC;border-radius:10px;font-size:13px;color:#2A3A33">Resumo administrativo gerado pela EmilIA a partir da agenda. Nenhuma cobrança ou mensagem foi enviada a pacientes: confirmações e cobranças continuam com a equipe.</p>'
 + '</div><p style="text-align:center;color:#8E9B93;font-size:11px;margin-top:14px">EmilIA · Grupo G29 · dados 100% fictícios</p></div></body></html>';
const assunto = 'EmilIA · Agenda de ' + d.toFormat('cccc, dd/MM') + ' · ' + ativas.length + ' paciente(s)';
return [{ json: { assunto, html: html.replace('__LOGO__', 'https://raw.githubusercontent.com/facanhaluisaaa-create/EmiliIA/main/apps/web/public/brand/logo-light.png'), total: ativas.length, data } }];
